import { SourceLink } from "@/components/app-link";
import type { Metadata } from "next";
import Link from "@/components/app-link";
import { communityDesignEntries } from "@/lib/content/community-design";
import { ORGANIZATIONS, ORGANIZATIONS_CHECKED, RELATIONSHIP_ORDER, hasDivisionRecord, isNativeCommunity, organizationHref } from "@/lib/content/hub/organizations";
import { DEPARTMENT_WIDE_GRANTS } from "@/lib/content/hub/record-findings";
import { catOneLine, catPaginate, catParam } from "@/lib/cat-paging";
import { CatList, CatPager, CatResultStatus, CatRow } from "@/components/cat-list";
import styles from "../hub.module.css";
import { ResourceDownloads } from "@/components/resource-downloads";

export const metadata: Metadata = {
  title: "Organizations connected with the Disability Services Division",
  description: "Grantees, contractors, partners and advisory members of the Disability Services Division, each with the public records behind the connection.",
};

const PER_PAGE = 12;
const BASE = "/community-outreach/organizations";

type Query = { community?: string | string[]; type?: string | string[]; q?: string | string[]; page?: string | string[] };

export default async function OrganizationDirectory({ searchParams }: { searchParams: Promise<Query> }) {
  const params = await searchParams;
  const community = catParam(params.community);
  const type = catParam(params.type);
  const q = catParam(params.q);
  const titles = new Map(communityDesignEntries().map(entry => [entry.id, entry.title]));
  const linked = [...new Set(ORGANIZATIONS.flatMap(org => org.communities))].filter(id => !isNativeCommunity(id)).sort((a, b) => (titles.get(a) ?? a).localeCompare(titles.get(b) ?? b));
  const query = q.toLowerCase();
  const shown = ORGANIZATIONS.filter(org =>
    (!community || org.communities.includes(community)) &&
    (!type || org.relationshipTypes.includes(type)) &&
    (!query || `${org.name} ${org.alsoKnownAs ?? ""} ${org.summary} ${org.whereItWorks}`.toLowerCase().includes(query)));
  const page = catPaginate(shown, catParam(params.page), PER_PAGE);
  const choices = { community, type, q };
  return <div className={styles.page}>
    <p className={styles.kicker}><Link href="/community-outreach">Community Outreach and Engagement</Link></p>
    <h1 className={styles.title}>Organizations connected with the Disability Services Division</h1>
    <p className={styles.lede}>Each organization here has a published record of working with the Disability Services Division as a grantee, contractor, partner or advisory member. Each page lists the records it rests on.</p>
    <p className={styles.note}>Being listed here does not mean the organization speaks for a whole community, and it is not a ranking. Some connections ended years ago. Confirm current details with the organization before you rely on them. Facts were checked on {ORGANIZATIONS_CHECKED}.</p>

    <p><SourceLink href="/documents/community-outreach/organizations-connected-with-the-disability-services-division.pdf" download>Download all organization pages as one PDF</SourceLink> (45 pages, 1 MB)</p>
    <details className="border-b border-line pb-3 print:hidden"><summary className="min-h-11 cursor-pointer py-2 font-semibold text-[#183247]">Download or share this page</summary><ResourceDownloads kind="community-outreach" id="organizations" noun="directory" /></details>

    <form method="get" action={BASE} className={styles.filters} role="search" aria-label="Filter organizations">
      <label htmlFor="org-q">Search<input id="org-q" name="q" type="search" defaultValue={q} /></label>
      <label htmlFor="org-community">Community<select id="org-community" name="community" defaultValue={community}><option value="">All communities</option>{linked.map(id => <option key={id} value={id}>{titles.get(id) ?? id}</option>)}</select></label>
      <label htmlFor="org-type">Connection<select id="org-type" name="type" defaultValue={type}><option value="">All connections</option>{RELATIONSHIP_ORDER.map(t => <option key={t} value={t}>{t}</option>)}</select></label>
      <button className={styles.button} type="submit">Show organizations</button>
      {community || type || q ? <Link href={BASE}>Clear filters</Link> : null}
    </form>

    <CatResultStatus page={page} noun="organization" nouns="organizations" of={ORGANIZATIONS.length} empty="No organization matches these filters." />
    {page.items.length ? <CatList label="Organizations">
      {page.items.map(org => <CatRow key={org.slug}
        title={<Link href={organizationHref(org.slug)}>{org.name}</Link>}
        line={catOneLine(org.summary)}
        meta={[org.kind, org.relationshipTypes.join(", "), org.closed ? "Closed" : "", !hasDivisionRecord(org) ? "Record names the Department of Human Services" : ""].filter(Boolean).join(" · ")} />)}
    </CatList> : <p><Link href={BASE}>Show all organizations</Link>.</p>}
    <CatPager page={page} basePath={BASE} params={choices} label="Organization result pages" />

    <details className="course-more-item">
      <summary><h2 id="department-title">Also on record with the Department of Human Services ({DEPARTMENT_WIDE_GRANTS.length})</h2></summary>
      <p>These grants are recorded with the Department of Human Services, but the records do not name the Disability Services Division. They are listed so the record is complete.</p>
      <ul className="list-disc space-y-3 pl-6">{DEPARTMENT_WIDE_GRANTS.map(grant => <li key={grant.organizations}>
        <strong>{grant.organizations}</strong>. {grant.program}, {grant.years}{grant.amounts ? `, ${grant.amounts}` : ""}. {grant.focus}{" "}
        <SourceLink href={grant.record.url}>{grant.record.title}, {grant.record.date}</SourceLink>.
      </li>)}</ul>
    </details>

    <details className="course-more-item">
      <summary><h2>Where the records come from</h2></summary>
      <p>Most connections come from the Disability Services Division&apos;s 2023 report to the Legislature, the list of Innovation Grant awards, Department of Human Services news releases, and the Minnesota law that sets up the Waiver Reimagine advisory task force. Where a record names the Department of Human Services but not the Disability Services Division, the organization&apos;s page says so.</p>
    </details>
  </div>;
}

import type { Metadata } from "next";
import Link from "@/components/app-link";
import {
  allAppliesTo,
  allPrograms,
  formatPolicyDate,
  getPoliciesData,
  policyHref,
  searchPolicies,
  type Policy,
} from "@/lib/content/hub/dsd-policies";
import { catOneLine, catPaginate, catParam } from "@/lib/cat-paging";
import { CatList, CatPager, CatResultStatus, CatRow } from "@/components/cat-list";
import styles from "../hub.module.css";
import { ResourceDownloads } from "@/components/resource-downloads";

export const metadata: Metadata = {
  title: "Policies that shape disability services",
  description: "Plain-language summaries of the Minnesota statutes, rules, manual pages, waiver plans, department policies, bulletins, federal rules and reports that shape disability services, each with its official source.",
};

const PER_PAGE = 12;
const BASE = "/community-outreach/policies";

type Query = { q?: string | string[]; search?: string | string[]; kind?: string | string[]; program?: string | string[]; "applies-to"?: string | string[]; page?: string | string[] };

function same(a: string, b: string): boolean {
  return a.trim().toLocaleLowerCase("en-US") === b.trim().toLocaleLowerCase("en-US");
}

/** The most recent date the policy carries, for its one-line row. */
function rowDate(p: Policy): string {
  if (p.lastUpdated) return `Last updated ${formatPolicyDate(p.lastUpdated)}`;
  if (p.effective) return `Effective ${formatPolicyDate(p.effective)}`;
  return `Checked ${formatPolicyDate(p.checked)}`;
}

export default async function PoliciesPage({ searchParams }: { searchParams: Promise<Query> }) {
  const query = await searchParams;
  const kind = catParam(query.kind);
  const program = catParam(query.program);
  const appliesTo = catParam(query["applies-to"]);
  const search = catParam(query.q) || catParam(query.search);
  const data = getPoliciesData();
  const kinds = data.kinds;
  const kindTitle = new Map(kinds.map(k => [k.id, k.title]));
  const programs = allPrograms();
  const groups = allAppliesTo();

  let matches = data.policies;
  if (kind) matches = matches.filter(p => p.kind === kind);
  if (program) matches = matches.filter(p => p.programs.some(name => same(name, program)));
  if (appliesTo) matches = matches.filter(p => p.appliesTo.some(name => same(name, appliesTo)));
  if (search) matches = searchPolicies(search, matches);
  // Keep the order of the kinds, as the catalog has always been read.
  const kindOrder = new Map(kinds.map((k, i) => [k.id, i]));
  matches = matches.slice().sort((a, b) => (kindOrder.get(a.kind) ?? 99) - (kindOrder.get(b.kind) ?? 99));
  const filtered = Boolean(kind || program || appliesTo || search);
  const page = catPaginate(matches, catParam(query.page), PER_PAGE);
  const params = { q: search, kind, program, "applies-to": appliesTo };
  const selectedKind = kinds.find(k => k.id === kind);

  return <div className={styles.page}>
    <p className={styles.kicker}><Link href="/community-outreach">Community Outreach and Engagement</Link></p>
    <h1 className={styles.title}>Policies that shape disability services</h1>
    <p className={styles.lede}>The statutes, rules, manual pages, waiver plans, department policies, bulletins, federal rules and reports that decide who gets home and community-based services in Minnesota, what they get, and who is responsible.</p>
    <p className={styles.note}>These are summaries written in plain language. The policy itself is the source document: each entry links to it. Check the date on the source before relying on it, because policies change. Facts checked on {formatPolicyDate(data.checked)}.</p>
    <details className="border-b border-line pb-3 print:hidden"><summary className="min-h-11 cursor-pointer py-2 font-semibold text-[#183247]">Download or share this page</summary><ResourceDownloads kind="community-outreach" id="policies" noun="policy catalog" /></details>
    <details className="course-more-item">
      <summary>About each kind of policy and how to use them</summary>
      <dl>{kinds.map(k => <div key={k.id} id={`kind-${k.id}`}>
        <dt><strong><Link href={`${BASE}?kind=${k.id}`}>{k.title}</Link></strong> ({data.policies.filter(p => p.kind === k.id).length})</dt>
        <dd style={{ margin: "0 0 0.75rem" }}>{k.intro}</dd>
      </div>)}</dl>
      <p><Link href="/community-outreach/how-the-system-connects">How the system connects</Link> shows where each policy sits between the Department of Human Services, lead agencies, providers and the people they serve. <Link href="/equity-review">Equity review</Link> holds the review tools. <Link href="/equity-review/analyze">Analyze a policy document</Link> to work through the text of a policy section by section.</p>
    </details>

    <form method="get" action={BASE} className={styles.filters} role="search" aria-label="Find a policy">
      <label htmlFor="policy-q">Search
        <input id="policy-q" type="search" name="q" defaultValue={search} placeholder="Words in a policy" />
      </label>
      <label htmlFor="policy-kind">Kind
        <select id="policy-kind" name="kind" defaultValue={kind}>
          <option value="">All kinds</option>
          {kinds.map(k => <option key={k.id} value={k.id}>{k.title}</option>)}
        </select>
      </label>
      <label htmlFor="policy-program">Program
        <select id="policy-program" name="program" defaultValue={program}>
          <option value="">All programs</option>
          {programs.map(name => <option key={name} value={name}>{name}</option>)}
        </select>
      </label>
      <label htmlFor="policy-applies-to">Applies to
        <select id="policy-applies-to" name="applies-to" defaultValue={appliesTo}>
          <option value="">Everyone</option>
          {groups.map(name => <option key={name} value={name}>{name}</option>)}
        </select>
      </label>
      <button className={styles.button} type="submit">Show</button>
      {filtered ? <Link href={BASE}>Show all policies</Link> : null}
    </form>

    {selectedKind ? <p>{selectedKind.intro}</p> : null}
    <CatResultStatus page={page} noun="policy" nouns="policies" of={data.policies.length} empty="No policy matches these filters. Try fewer filters or different words." />
    {page.items.length ? <CatList label="Policies">
      {page.items.map(p => <CatRow key={p.id} id={`policy-${p.id}`}
        title={<Link href={policyHref(p.id)}>{p.title}</Link>}
        line={catOneLine(p.summary)}
        meta={`${kindTitle.get(p.kind) ?? p.kind} · ${rowDate(p)}`} />)}
    </CatList> : null}
    <CatPager page={page} basePath={BASE} params={params} label="Policy result pages" />

    <p>
      <Link href="/community-outreach/how-the-system-connects">How the system connects</Link> · <Link href="/equity-review">Equity review</Link> · <Link href="/equity-review/analyze">Analyze a policy document</Link>
    </p>
  </div>;
}

import { SourceLink } from "@/components/app-link";
import type { Metadata } from "next";
import Link from "@/components/app-link";
import { getCountyAgencies, sharedAgencies } from "@/lib/content/hub/county-agencies";
import { catHref, catPaginate, catParam } from "@/lib/cat-paging";
import { CatExpandRow, CatList, CatPager, CatResultStatus, catStyles } from "@/components/cat-list";
import { CatHashLocator } from "@/components/cat-hash-locator";
import styles from "../hub.module.css";
import { ResourceDownloads } from "@/components/resource-downloads";

export const metadata: Metadata = {
  title: "County agencies",
  description: "The agency that serves people in each Minnesota county for Department of Human Services disability programs, including counties that share one agency.",
};

const PER_PAGE = 12;
const BASE = "/community-outreach/county-agencies";
const LETTERS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("");

type Query = { q?: string | string[]; letter?: string | string[]; page?: string | string[]; find?: string | string[] };

export default async function CountyAgenciesPage({ searchParams }: { searchParams: Promise<Query> }) {
  const params = await searchParams;
  const q = catParam(params.q);
  const letterParam = catParam(params.letter).toUpperCase();
  const find = catParam(params.find);
  const data = getCountyAgencies();
  const all = data.counties.slice().sort((a, b) => a.county.localeCompare(b.county, "en-US"));
  const query = q.toLowerCase();
  const searched = all.filter(c => !query || `${c.county} ${c.agencyName}`.toLowerCase().includes(query));
  const present = new Set(searched.map(c => c.county.charAt(0).toUpperCase()));
  const letter = LETTERS.includes(letterParam) && present.has(letterParam) ? letterParam : "";
  const counties = searched.filter(c => !letter || c.county.toUpperCase().startsWith(letter));
  const page = catPaginate(counties, catParam(params.page), PER_PAGE, find ? c => `county-${c.fips}` === find : undefined);
  const choices = { q, letter };
  const shared = sharedAgencies();
  return <div className={styles.page}>
    <CatHashLocator prefix="county-" />
    <p className={styles.kicker}><Link href="/community-outreach">Community Outreach and Engagement</Link></p>
    <h1 className={styles.title}>County agencies</h1>
    <p className={styles.lede}>{data.description}</p>
    <details className="border-b border-line pb-3 print:hidden"><summary className="min-h-11 cursor-pointer py-2 font-semibold text-[#183247]">Download or share this page</summary><ResourceDownloads kind="community-outreach" id="county-agencies" noun="county agency directory" /></details>
    <p className={styles.note}>Counties are where most people meet the disability services system: assessments, waivers and case management happen there. Most counties publish one human services line rather than a separate disability line. Details were checked on {data.checked}; confirm them before you share them.</p>
    {data.tribalNations.map(link => <p key={link.url}>{link.note} <SourceLink href={link.url}>{link.title}</SourceLink>.</p>)}

    <details className="course-more-item">
      <summary><h2 id="shared-title">Counties that share one agency ({shared.length})</h2></summary>
      <ul className="list-disc pl-6">{shared.map(agency => <li key={agency.agencyId}>{agency.website ? <SourceLink href={agency.website}>{agency.agencyName}</SourceLink> : agency.agencyName}: {agency.counties.join(", ")}</li>)}</ul>
    </details>

    <section className={styles.section} aria-labelledby="counties-title">
      <h2 id="counties-title">All {all.length} counties</h2>
      <form method="get" action={BASE} className={styles.filters} role="search" aria-label="Find a county">
        <label htmlFor="county-q">County or agency<input id="county-q" name="q" type="search" defaultValue={q} /></label>
        {letter ? <input type="hidden" name="letter" value={letter} /> : null}
        <button className={styles.button} type="submit">Find</button>
        {q || letter ? <Link href={BASE}>Show all counties</Link> : null}
      </form>
      <nav className={catStyles.jump} aria-label="Counties by first letter">
        <ul>
          <li><Link href={catHref(BASE, { q })} aria-current={!letter ? "page" : undefined}>All</Link></li>
          {LETTERS.map(l => <li key={l}>{present.has(l)
            ? <Link href={catHref(BASE, { q, letter: l })} aria-current={l === letter ? "page" : undefined}>{l}</Link>
            : <span className={catStyles.none} aria-hidden="true">{l}</span>}</li>)}
        </ul>
      </nav>
      <CatResultStatus page={page} noun="county" nouns="counties" of={all.length} empty="No county matches that search." />
      {page.items.length ? <CatList label="Counties">
        {page.items.map(c => <CatExpandRow key={c.fips} id={`county-${c.fips}`}
          title={c.county}
          line={c.agencyName}>
          <p>Agency: {c.website ? <SourceLink href={c.website}>{c.agencyName}</SourceLink> : c.agencyName}{c.shared ? <span className={styles.small}> (shared with {c.sharedCounties.filter(n => n !== c.county).join(", ")})</span> : null}</p>
          <p>Phone: {c.phone ? <><SourceLink href={`tel:${c.phone.replace(/[^0-9]/g, "")}`}>{c.phone}</SourceLink> <span className={styles.small}>{c.phoneLabel}</span></> : <span className={styles.small}>Not published</span>}</p>
          <p className={styles.small}>{c.status === "partial" ? "Partly confirmed. " : ""}{c.notes} <SourceLink href={c.sourceUrl}>Source</SourceLink></p>
        </CatExpandRow>)}
      </CatList> : null}
      <CatPager page={page} basePath={BASE} params={choices} label="County result pages" />
    </section>

    <details className="course-more-item">
      <summary><h2>Sources</h2></summary>
      <ul className="list-disc pl-6">{data.sources.map(s => <li key={s.id}>{s.url ? <SourceLink href={s.url}>{s.title}</SourceLink> : s.title}: {s.usedFor}</li>)}</ul>
    </details>
    <p><Link href="/community-outreach/how-the-system-connects">How the system connects</Link> · <Link href="/community-outreach/providers">Providers and designated agencies</Link> · <Link href="/community-outreach/county-map">Minnesota county map</Link></p>
  </div>;
}

import { FocusedSections } from "@/components/focused-sections";

import { SourceLink } from "@/components/app-link";
import type { Metadata } from "next";
import Link from "@/components/app-link";
import { getOfficialProviders } from "@/lib/content/hub/official-providers";
import { ORGANIZATIONS, organizationHref } from "@/lib/content/hub/organizations";
import { getCountyAgencies } from "@/lib/content/hub/county-agencies";
import styles from "../hub.module.css";
import { ResourceDownloads } from "@/components/resource-downloads";

export const metadata: Metadata = {
  title: "Providers and designated agencies",
  description: "Centers for Independent Living, Area Agencies on Aging, contracted health plans, Disability Hub MN, licensed providers and other state-designated agencies, by county.",
};

export default async function ProvidersPage({ searchParams }: { searchParams: Promise<{ county?: string }> }) {
  const { county = "" } = await searchParams;
  const data = getOfficialProviders();
  const counties = getCountyAgencies().counties.map(c => c.county);
  const matches = (entryCounties: string[]) => !county || entryCounties.includes("Statewide") || entryCounties.includes(county);
  const licensed = data.licensedProviderCounts;
  const orgSlug = (name?: string) => name ? ORGANIZATIONS.find(org => org.name === name)?.slug : undefined;
  return <div className={styles.page}><FocusedSections>
    <p className={styles.kicker}><Link href="/community-outreach">Community Outreach and Engagement</Link></p>
    <h1 className={styles.title}>Providers and designated agencies</h1>
    <p className={styles.lede}>Organizations that the State of Minnesota designates, contracts, licenses or certifies to serve people with disabilities, and which counties each one serves. Each entry names the public record of its designation.</p>
    <details className="border-b border-line pb-3 print:hidden"><summary className="min-h-11 cursor-pointer py-2 font-semibold text-[#183247]">Download or share this page</summary><ResourceDownloads kind="community-outreach" id="providers" noun="provider directory" /></details>
    <p className={styles.note}>Designation is a matter of public record; it is not a judgment of quality, and it is not a referral. Confirm current details with the organization. Facts checked on {data.checked}.</p>
    <p>{data.tribalNote} <Link href="/learn/tribal-referral">Native American and Tribal-specific guidance</Link>.</p>

    <form method="get" className={styles.filters} aria-label="Choose a county">
      <label>County<select name="county" defaultValue={county}><option value="">All counties</option>{counties.map(name => <option key={name} value={name}>{name}</option>)}</select></label>
      <button className={styles.button} type="submit">Show</button>
      {county ? <Link href="/community-outreach/providers">Show all counties</Link> : null}
    </form>

    {data.categories.map(category => {
      const entries = category.entries.filter(entry => matches(entry.counties));
      return <section className={styles.section} key={category.id} aria-labelledby={`cat-${category.id}`}>
        <h2 id={`cat-${category.id}`}>{category.title}</h2>
        <p>{category.intro}</p>
        {category.id === "licensed-providers" ? <p className={styles.small}>{data.licensedProviderCountsNote}</p> : null}
        <p className={styles.small}>Designated by: {category.designatedBy}</p>
        {entries.length ? <ul className={styles.grid} style={{ listStyle: "none", padding: 0 }}>{entries.map(entry => <li className={styles.card} key={entry.name}>
          <h3>{entry.website ? <SourceLink href={entry.website}>{entry.name}</SourceLink> : entry.name}</h3>
          {entry.alsoKnownAs?.length ? <p className={styles.meta}>Also known as {entry.alsoKnownAs.join(", ")}</p> : null}
          <p>{entry.what}</p>
          <p className={styles.small}>Counties: {entry.counties.length ? (entry.counties.length > 20 && !county ? `${entry.counties.length} counties` : entry.counties.join(", ")) : "No published county list"}</p>
          {entry.programCounties && county ? <p className={styles.small}>In {county}: {[entry.programCounties.specialNeedsBasicCare.includes(county) ? "Special Needs BasicCare" : "", entry.programCounties.seniorHealthOptions.includes(county) ? "Minnesota Senior Health Options or Senior Care Plus" : ""].filter(Boolean).join("; ") || "not offered"}</p> : null}
          {orgSlug(entry.organizationsName) ? <p className={styles.small}><Link href={organizationHref(orgSlug(entry.organizationsName)!)}>Its record with the Disability Services Division</Link></p> : null}
          {entry.phone ? <p className={styles.small}>Phone: <SourceLink href={`tel:${entry.phone.replace(/[^0-9]/g, "")}`}>{entry.phone}</SourceLink></p> : null}
          <p className={styles.small}>Record: <SourceLink href={entry.source.url}>{entry.source.title}</SourceLink>{entry.source.date ? `, ${entry.source.date}` : ""}</p>
        </li>)}</ul> : <p>None listed for {county}.</p>}
      </section>;
    })}

    <section className={styles.section} aria-labelledby="licensed-title">
      <h2 id="licensed-title">Finding licensed providers</h2>
      <p>Providers of home and community-based services are licensed under Minnesota Statutes chapter 245D by the Department of Human Services. There are too many to list here; use the official lookups below to find current licensed providers by county and service.</p>
      {licensed ? <>
        <p>Active licenses by county, from <SourceLink href={licensed.source.url}>{licensed.source.title}</SourceLink>{licensed.date ? ` (${licensed.date})` : ""}:</p>
        <div role="region" aria-label="Licensed providers by county" tabIndex={0} style={{ overflowX: "auto" }}>
          <table className={styles.table}><thead><tr><th scope="col">County</th><th scope="col">Active licenses</th></tr></thead>
            <tbody>{Object.entries(licensed.byCounty).filter(([name]) => !county || name === county).sort(([a], [b]) => a.localeCompare(b)).map(([name, count]) => <tr key={name}><th scope="row">{name}</th><td>{count.toLocaleString("en-US")}</td></tr>)}</tbody></table>
        </div>
      </> : null}
      <h3 className="mt-4 font-bold">Official lookups</h3>
      <ul className="list-disc pl-6">{data.lookups.map(lookup => <li key={lookup.url}><SourceLink href={lookup.url}>{lookup.name}</SourceLink>: {lookup.what}</li>)}</ul>
    </section>

    <p><Link href="/community-outreach/how-the-system-connects">How the system connects</Link> · <Link href="/community-outreach/county-agencies">County agencies</Link> · <Link href="/community-outreach/county-map">Minnesota county map</Link></p>
  </FocusedSections></div>;
}
